INSERT INTO Brands (BrandId, BrandName, LogoUrl, Description) VALUES
(1, 'ASUS', '/images/brands/asus.png', 'Thương hiệu hàng đầu với dòng ROG, TUF Gaming, Zenbook, Vivobook.'),
(2, 'Dell', '/images/brands/dell.png', 'Nổi tiếng bền bỉ với dòng XPS cao cấp, Alienware gaming và Inspiron/Vostro.'),
(3, 'Lenovo', '/images/brands/lenovo.png', 'Dòng Legion gaming đỉnh cao, ThinkPad doanh nhân và IdeaPad/Yoga.'),
(4, 'Apple', '/images/brands/apple.png', 'Dòng MacBook Air, MacBook Pro cao cấp chạy chip Apple Silicon độc quyền.'),
(5, 'Acer', '/images/brands/acer.png', 'Thế mạnh cấu hình cao giá tốt với Nitro 5/V, Predator Helios và Swift.'),
(6, 'HP', '/images/brands/hp.png', 'Đa dạng phân khúc với Victus gaming, OMEN, Pavilion, Envy và Spectre cao cấp.'),
(7, 'MSI', '/images/brands/msi.png', 'Chuyên laptop gaming Katana, Cyborg, Raider, Stealth và dòng Modern văn phòng.'),
(8, 'LG', '/images/brands/lg.png', 'Dòng LG gram siêu nhẹ, pin khủng, độ bền cao cho doanh nhân và văn phòng.'),
(9, 'Gigabyte', '/images/brands/gigabyte.png', 'Laptop gaming cấu hình khỏe giá cạnh tranh G5/G6 và Aorus chuyên nghiệp.'),
(10, 'Microsoft', '/images/brands/microsoft.png', 'Dòng Surface sang trọng, màn hình cảm ứng sắc nét tỉ lệ 3:2 độc đáo.');
INSERT INTO Categories (CategoryId, CategoryName, Description) VALUES
(1, 'Laptop Gaming', 'Trang bị CPU hiệu năng cao (dòng H/HX), GPU rời NVIDIA GeForce RTX, tản nhiệt buồng hơi, màn hình tần số quét từ 144Hz trở lên.'),
(2, 'Laptop Học tập - Văn phòng', 'Thiết kế thực dụng, thời lượng pin tốt, bàn phím gõ êm, tối ưu tác vụ tin học văn phòng, lướt web, học online.'),
(3, 'Laptop Đồ họa - Kỹ thuật', 'Màn hình chuẩn màu sRGB/DCI-P3, CPU/GPU mạnh mẽ tối ưu cho AutoCAD, SolidWorks, Premiere, lập trình và render.'),
(4, 'Laptop Mỏng nhẹ - Doanh nhân', 'Trọng lượng dưới 1.4kg, vỏ kim loại/magie cao cấp, độ bảo mật cao (vân tay, nhận diện khuôn mặt), thiết kế sang trọng.'),
(5, 'Workstation Di Động', 'Trạm làm việc di động với CPU cực mạnh, RAM mở rộng lớn, GPU chuyên dụng Studio/Quadro, độ bền chuẩn quân đội.');
